import{relative}from"node:path";import pc from"#compiled/picocolors/index.js";import{formatNodeEngineOverrideWarning}from"#setup/node-engine.js";function reportExistingProjectChanges(e,t){e.log(`Updated existing project:`);for(let n of t.filesWritten)e.log(`  Created ${relative(t.projectPath,n).replaceAll(`\\`,`/`)}`);t.dependenciesAdded.length>0&&e.log(`  Added dependencies: ${t.dependenciesAdded.join(`, `)}`);for(let n of t.configurationFilesChanged)e.log(`  Updated ${n}`);t.nodeEngineOverride!==void 0&&e.log(pc.yellow(`  ⚠ ${formatNodeEngineOverrideWarning(t.nodeEngineOverride)}`))}export{reportExistingProjectChanges};